CREATE   VIEW dbo.[Sales_SalesOrderHeader] AS SELECT CAST([SalesOrderID] AS int) AS [SalesOrderID], CAST([RevisionNumber] AS tinyint) AS [RevisionNumber], CAST([OrderDate] AS datetime2(6)) AS [OrderDate], CAST([DueDate] AS datetime2(6)) AS [DueDate], CAST([ShipDate] AS datetime2(6)) AS [ShipDate], CAST([Status] AS tinyint) AS [Status], CAST([OnlineOrderFlag] AS bit) AS [OnlineOrderFlag], CAST([SalesOrderNumber] AS VARCHAR(25)) AS [SalesOrderNumber], CAST([PurchaseOrderNumber] AS VARCHAR(25)) AS [PurchaseOrderNumber], CAST([AccountNumber] AS VARCHAR(15)) AS [AccountNumber], CAST([CustomerID] AS int) AS [CustomerID], CAST([SalesPersonID] AS int) AS [SalesPersonID], CAST([TerritoryID] AS int) AS [TerritoryID], CAST([BillToAddressID] AS int) AS [BillToAddressID], CAST([ShipToAddressID] AS int) AS [ShipToAddressID], CAST([ShipMethodID] AS int) AS [ShipMethodID], CAST([CreditCardID] AS int) AS [CreditCardID], CAST([CreditCardApprovalCode] AS varchar(15)) AS [CreditCardApprovalCode], CAST([CurrencyRateID] AS int) AS [CurrencyRateID], CAST([SubTotal] AS money) AS [SubTotal], CAST([TaxAmt] AS money) AS [TaxAmt], CAST([Freight] AS money) AS [Freight], CAST([TotalDue] AS money) AS [TotalDue], CAST([Comment] AS VARCHAR(128)) AS [Comment], CAST([rowguid] AS uniqueidentifier) AS [rowguid], CAST([ModifiedDate] AS datetime2(6)) AS [ModifiedDate] FROM [lh_bronze].[bronze].[Sales_SalesOrderHeader];

